{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Pethidine, a synthetic opioid with an N-methyl piperidine, has absolute oral bioavailability of 0.52 (0.47–0.61) in healthy subjects, directly supporting F ≥20% for an opioid-like analgesic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Samidorphan, a morphinan opioid modulator sharing the fused polycyclic opioid scaffold, has absolute oral bioavailability of 69% in healthy volunteers, supporting high oral bioavailability for the query's morphinan framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Morphine, the closest morphinan analog, has average oral bioavailability of about 38% in cancer patients and healthy volunteers, supporting F ≥20% despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Raclopride, a methoxy-substituted aromatic drug with a basic amine, has absolute oral bioavailability of 65±15% in healthy volunteers, supporting high F for a small molecule with similar polar/lipophilic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pentazocine, an opioid analgesic, had mean oral bioavailability of 18% in healthy subjects, below the 20% threshold; this is contradictory evidence, but its different benzomorphan scaffold and extensive first-pass metabolism limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is hydrocodone, a morphinan opioid with a methoxy group, ketone, and N-methyl. The strongest transferable evidence from pethidine (F≈0.52), samidorphan (69%), morphine (≈38%), and raclopride (65%) supports high oral bioavailability. The only clearly low-F opioid analogue, pentazocine (18%), is less transferable due to its distinct benzomorphan scaffold and extensive first-pass metabolism. Overall, F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct hydrocodone absolute bioavailability record is present in the evidence set.",
    "Morphine bioavailability data are variable and formulation-dependent, introducing some uncertainty in extrapolating the exact F value.",
    "Pentazocine low F shows that opioid first-pass metabolism can be substantial, so species/formulation differences could affect the exact F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

